function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function buildFineTuneSpec(o){
  o=o||{};
  var name=String(o.name||'').trim()||'UntitledFT';
  var base=String(o.base||'').trim()||'（待填写基模）';
  var task=String(o.task||'').trim()||'（待填写微调任务）';
  var method=String(o.method||'LoRA').trim()||'LoRA';
  var dataDesc=String(o.dataDesc||'').trim()||'（待补充数据描述）';
  var dataSize=String(o.dataSize||'').trim()||'（待补充数据量）';
  var epochs=parseInt(o.epochs,10)||3; if(epochs<1)epochs=1; if(epochs>100)epochs=100;
  var lr=String(o.lr||'2e-5').trim()||'2e-5';
  var bs=parseInt(o.batchSize,10)||8; if(bs<1)bs=1; if(bs>512)bs=512;
  var hw=String(o.hardware||'').trim()||'单卡 GPU（如 A100 80G）';
  var metric=String(o.metric||'').trim()||'（待填写评估指标）';
  var notes=splitLines(o.notes);
  var risks=['过拟合：监控验证集指标，必要时早停或降学习率','灾难性遗忘：对通用能力保留评测集','数据泄露：确保训练/验证/测试严格隔离','成本超支：预估显存与训练时长后再启动'];
  var lines=[];
  lines.push('# 微调规格书：'+name);
  lines.push('');
  lines.push('## 一、目标与任务');
  lines.push('- 任务：'+task);
  lines.push('- 验收：在目标评估集上相较基模取得可量化提升且不明显退化通用能力');
  lines.push('');
  lines.push('## 二、基模与方法');
  lines.push('- 基模：'+base);
  lines.push('- 方法：'+method);
  lines.push('');
  lines.push('## 三、数据与预处理');
  lines.push('- 描述：'+dataDesc);
  lines.push('- 规模：'+dataSize);
  lines.push('- 预处理：去重、清洗、格式化为（指令, 输入, 输出）三元组；按 8:1:1 切分');
  lines.push('');
  lines.push('## 四、训练超参');
  lines.push('- 轮数 epochs：'+epochs);
  lines.push('- 学习率 lr：'+lr);
  lines.push('- 批次 batch_size：'+bs);
  lines.push('');
  lines.push('## 五、资源与环境');
  lines.push('- 硬件：'+hw);
  lines.push('- 框架：PyTorch / Transformers + 对应 PEFT 库；启用混合精度与梯度检查点');
  lines.push('');
  lines.push('## 六、评估');
  lines.push('- 指标：'+metric);
  lines.push('- 方式：留出测试集 + 人工抽样复核；对比基模基线');
  lines.push('');
  lines.push('## 七、风险与回滚');
  risks.forEach(function(r){ lines.push('- '+r); });
  if(notes.length){ lines.push(''); lines.push('## 八、补充说明'); notes.forEach(function(n){ lines.push('- '+n); }); }
  return {title:name+' 微调规格书', epochs:epochs, batchSize:bs, hasNotes:notes.length>0, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, buildFineTuneSpec:buildFineTuneSpec};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FineTuneSpecForgePure = EXPORTS; }
